import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Sparkles, Plus, Trash2, Edit3, Trophy, AlertTriangle, Loader2, Check } from 'lucide-react';

const API_URL = '/api.php';

// Landing editor → "Text A/B": pick a text on the page, add variants (by
// hand or generated by the AI assistant's model), and the tracker swaps the
// text per visit and moves traffic to the variant that sends more visitors
// on to the offer (core/TextTests.php).
export default function TextTestsTab({ landingId, landingType, t, language }) {
    const [data, setData] = useState(null);
    const [aiReady, setAiReady] = useState(false);
    const [form, setForm] = useState(null);
    const [candidates, setCandidates] = useState(null);
    const [gen, setGen] = useState({ count: 4, instructions: '', busy: false, error: null });
    const [busy, setBusy] = useState(false);
    const [message, setMessage] = useState(null);

    const load = async () => {
        try {
            const res = await axios.get(API_URL, { params: { action: 'text_tests', landing_id: landingId } });
            setData(res.data.status === 'success' ? res.data.data : { tests: [], local: false });
        } catch { setData({ tests: [], local: false }); }
    };

    useEffect(() => {
        if (!landingId) return;
        load();
        axios.get(API_URL, { params: { action: 'ai_status' } })
            .then(res => setAiReady(res.data.status === 'success' && !!res.data.data.configured))
            .catch(() => {});
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [landingId]);

    if (!landingId) {
        return <p className="text-sm" style={{ color: 'var(--color-text-muted)' }}>{t('textTests.saveFirst')}</p>;
    }
    if (!data) return null;
    if (landingType !== 'local' || !data.local) {
        return (
            <div className="rounded-xl p-4 text-sm" style={{ border: '1px solid var(--color-border)', color: 'var(--color-text-secondary)' }}>
                {t('textTests.localOnly')}
            </div>
        );
    }

    const openNew = async () => {
        setMessage(null);
        setForm({ id: null, name: '', original_text: '', mode: 'auto', is_active: true, variants: [{ text: '', is_active: true }], suggestions: [] });
        if (!candidates) {
            try {
                const res = await axios.get(API_URL, { params: { action: 'text_test_candidates', landing_id: landingId } });
                setCandidates(res.data.status === 'success' ? res.data.data : []);
            } catch { setCandidates([]); }
        }
    };
    const openEdit = (test) => {
        setMessage(null);
        setForm({
            id: test.id, name: test.name, original_text: test.original_text, mode: test.mode, is_active: !!test.is_active,
            variants: test.variants.filter(v => !v.is_original).map(v => ({ id: v.id, text: v.text, is_active: !!v.is_active, source: v.source })),
            suggestions: []
        });
    };

    const setVariant = (i, patch) => setForm(f => ({ ...f, variants: f.variants.map((v, j) => (j === i ? { ...v, ...patch } : v)) }));

    const generate = async () => {
        if (!form.original_text.trim()) return;
        setGen(g => ({ ...g, busy: true, error: null }));
        try {
            const res = await axios.post(`${API_URL}?action=ai_text_variants`, {
                landing_id: landingId, original_text: form.original_text, count: gen.count, instructions: gen.instructions, lang: language
            });
            if (res.data.status === 'success') {
                const have = new Set(form.variants.map(v => v.text.trim().toLowerCase()));
                const fresh = (res.data.data.variants || []).filter(x => !have.has(x.trim().toLowerCase()));
                setForm(f => ({ ...f, suggestions: [...fresh.map(text => ({ text, picked: true })), ...f.suggestions] }));
                setGen(g => ({ ...g, busy: false }));
            } else {
                setGen(g => ({ ...g, busy: false, error: res.data.message || res.data.code }));
            }
        } catch {
            setGen(g => ({ ...g, busy: false, error: t('common.networkError') }));
        }
    };

    const save = async () => {
        setBusy(true);
        setMessage(null);
        const variants = [
            ...form.variants.filter(v => v.text.trim()),
            ...form.suggestions.filter(s => s.picked).map(s => ({ text: s.text, is_active: true, source: 'ai' }))
        ];
        try {
            const res = await axios.post(`${API_URL}?action=text_test_save`, {
                id: form.id, landing_id: landingId, name: form.name, original_text: form.original_text,
                mode: form.mode, is_active: form.is_active, variants
            });
            if (res.data.status === 'success') {
                setForm(null);
                setMessage({ ok: true, text: t('textTests.saved') });
                await load();
            } else {
                setMessage({ ok: false, text: t(`textTests.error.${res.data.code}`, res.data.message || res.data.code) });
            }
        } catch {
            setMessage({ ok: false, text: t('common.networkError') });
        } finally {
            setBusy(false);
        }
    };

    const toggle = async (test) => {
        await axios.post(`${API_URL}?action=text_test_save`, {
            id: test.id, landing_id: landingId, name: test.name, original_text: test.original_text, mode: test.mode,
            is_active: !test.is_active,
            variants: test.variants.filter(v => !v.is_original).map(v => ({ id: v.id, text: v.text, is_active: !!v.is_active, source: v.source }))
        }).catch(() => {});
        load();
    };
    const remove = async (test) => {
        if (!window.confirm(t('textTests.confirmDelete'))) return;
        await axios.post(`${API_URL}?action=text_test_delete`, { id: test.id, landing_id: landingId }).catch(() => {});
        load();
    };

    const muted = { color: 'var(--color-text-muted)' };
    const box = { border: '1px solid var(--color-border)', borderRadius: 12, padding: 12 };
    const pct = (v) => (v === null || v === undefined ? '—' : `${Number(v).toFixed(1)}%`);

    return (
        <div className="space-y-4" data-testid="text-tests-tab">
            <p className="text-xs" style={muted}>{t('textTests.intro')}</p>

            {data.tests.map(test => {
                const winner = test.winner_variant_id;
                return (
                    <div key={test.id} style={{ ...box, opacity: test.is_active ? 1 : 0.65 }} data-testid="text-test">
                        <div className="flex items-center gap-2 mb-2">
                            <input type="checkbox" checked={!!test.is_active} onChange={() => toggle(test)} title={t('textTests.active')} />
                            <div className="flex-1 min-w-0">
                                <div className="text-sm font-semibold truncate">{test.name}</div>
                                <div className="text-[11px]" style={muted}>
                                    {test.mode === 'auto' ? t('textTests.modeAuto') : t('textTests.modeEqual')}
                                </div>
                            </div>
                            <button type="button" className="btn btn-ghost btn-icon p-1.5" onClick={() => openEdit(test)} title={t('common.edit')}><Edit3 className="w-4 h-4" /></button>
                            <button type="button" className="btn btn-ghost btn-icon p-1.5" onClick={() => remove(test)} title={t('common.delete')}><Trash2 className="w-4 h-4" /></button>
                        </div>
                        {!test.found_on_page && (
                            <div className="flex items-center gap-2 text-xs mb-2" style={{ color: 'var(--color-warning, #f59e0b)' }}>
                                <AlertTriangle className="w-4 h-4" /> {t('textTests.notFound')}
                            </div>
                        )}
                        <div className="overflow-x-auto">
                            <table className="w-full text-xs">
                                <thead>
                                    <tr style={muted}>
                                        <th className="text-left py-1 pr-2">{t('textTests.variant')}</th>
                                        <th className="text-right py-1 px-2">{t('textTests.views')}</th>
                                        <th className="text-right py-1 px-2" title={t('textTests.ctrHint')}>{t('textTests.ctr')}</th>
                                        <th className="text-right py-1 px-2">{t('textTests.conversions')}</th>
                                        <th className="text-right py-1 px-2" title={t('textTests.probHint')}>{t('textTests.prob')}</th>
                                        <th className="text-right py-1 pl-2">{t('textTests.share')}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {test.variants.map(v => (
                                        <tr key={v.id} style={{ borderTop: '1px solid var(--color-border)', opacity: v.is_active ? 1 : 0.5 }}>
                                            <td className="py-1.5 pr-2" style={{ maxWidth: 320 }}>
                                                <div className="flex items-center gap-1.5">
                                                    {winner === v.id && <Trophy className="w-3.5 h-3.5 flex-shrink-0" style={{ color: '#f59e0b' }} />}
                                                    <span className="break-words">{v.text}</span>
                                                </div>
                                                <div className="text-[10px]" style={muted}>
                                                    {v.is_original ? t('textTests.original') : (v.source === 'ai' ? t('textTests.byAi') : '')}
                                                </div>
                                            </td>
                                            <td className="text-right px-2 tabular-nums">{(v.stats?.views || 0).toLocaleString()}</td>
                                            <td className="text-right px-2 tabular-nums font-semibold">{pct(v.stats?.ctr)}</td>
                                            <td className="text-right px-2 tabular-nums">{v.stats?.conversions || 0}</td>
                                            <td className="text-right px-2 tabular-nums">{v.prob_best === null || v.prob_best === undefined ? '—' : `${Math.round(v.prob_best * 100)}%`}</td>
                                            <td className="text-right pl-2 tabular-nums">{test.mode === 'equal' ? '=' : `${v.weight}%`}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        {winner && <div className="text-xs mt-2" style={{ color: 'var(--color-success)' }}>{t('textTests.winnerNote')}</div>}
                    </div>
                );
            })}

            {!form && (
                <button type="button" className="btn btn-secondary text-xs" onClick={openNew} data-testid="text-test-new">
                    <Plus className="w-3.5 h-3.5" /> {t('textTests.new')}
                </button>
            )}

            {form && (
                <div style={{ ...box, display: 'flex', flexDirection: 'column', gap: 10 }} data-testid="text-test-form">
                    {!form.id && (
                        <div>
                            <div className="text-xs font-semibold mb-1">{t('textTests.step1')}</div>
                            {candidates === null ? (
                                <div className="text-xs flex items-center gap-2" style={muted}><Loader2 className="w-3.5 h-3.5 animate-spin" />{t('common.loading')}</div>
                            ) : candidates.length > 0 ? (
                                <div className="flex flex-col gap-1 max-h-48 overflow-y-auto pr-1">
                                    {candidates.map((c, i) => (
                                        <button key={i} type="button" onClick={() => setForm(f => ({ ...f, original_text: c.text, name: f.name || c.text.slice(0, 60) }))}
                                            className="text-left text-xs px-2 py-1 rounded-lg border flex items-center gap-2"
                                            style={{ borderColor: form.original_text === c.text ? 'var(--color-primary)' : 'var(--color-border)' }} data-testid="text-candidate">
                                            <span className="text-[10px] uppercase font-bold w-10 flex-shrink-0" style={muted}>{c.tag}</span>
                                            <span className="break-words">{c.text}</span>
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-xs" style={muted}>{t('textTests.noCandidates')}</p>
                            )}
                        </div>
                    )}
                    <label className="flex flex-col gap-1 text-xs" style={muted}>
                        {t('textTests.originalLabel')}
                        <textarea className="input text-xs" rows={2} value={form.original_text}
                            onChange={e => setForm({ ...form, original_text: e.target.value })} />
                    </label>
                    <label className="flex flex-col gap-1 text-xs" style={muted}>
                        {t('textTests.name')}
                        <input className="input text-xs" style={{ padding: '0.3rem 0.6rem' }} value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} />
                    </label>

                    <div className="text-xs font-semibold">{t('textTests.step2')}</div>
                    {form.variants.map((v, i) => (
                        <div key={i} className="flex items-center gap-2">
                            <input type="checkbox" checked={!!v.is_active} onChange={e => setVariant(i, { is_active: e.target.checked })} title={t('textTests.active')} />
                            <input className="input text-xs flex-1" style={{ padding: '0.3rem 0.6rem' }} value={v.text}
                                placeholder={t('textTests.variantPlaceholder')} onChange={e => setVariant(i, { text: e.target.value })} />
                            <button type="button" className="btn btn-ghost btn-icon p-1" onClick={() => setForm(f => ({ ...f, variants: f.variants.filter((_, j) => j !== i) }))}><Trash2 className="w-3.5 h-3.5" /></button>
                        </div>
                    ))}
                    {form.variants.length + form.suggestions.filter(s => s.picked).length < 7 && (
                        <button type="button" className="btn btn-ghost text-xs" style={{ alignSelf: 'flex-start' }}
                            onClick={() => setForm(f => ({ ...f, variants: [...f.variants, { text: '', is_active: true }] }))}>
                            <Plus className="w-3.5 h-3.5" /> {t('textTests.addVariant')}
                        </button>
                    )}

                    <div className="rounded-xl p-3 space-y-2" style={{ border: '1px dashed color-mix(in srgb, #8b5cf6 45%, var(--color-border))' }}>
                        <div className="flex items-center gap-2 text-xs font-semibold"><Sparkles className="w-4 h-4" style={{ color: '#8b5cf6' }} />{t('textTests.aiTitle')}</div>
                        {aiReady ? (
                            <>
                                <div className="flex flex-wrap gap-2 items-center">
                                    <select className="form-select text-xs" style={{ width: 90 }} value={gen.count} onChange={e => setGen({ ...gen, count: Number(e.target.value) })}>
                                        {[2, 3, 4, 5, 6].map(n => <option key={n} value={n}>{n}</option>)}
                                    </select>
                                    <input className="input text-xs flex-1" style={{ padding: '0.3rem 0.6rem', minWidth: 160 }} value={gen.instructions}
                                        placeholder={t('textTests.aiInstructions')} onChange={e => setGen({ ...gen, instructions: e.target.value })} />
                                    <button type="button" className="btn btn-primary text-xs" disabled={gen.busy || !form.original_text.trim()} onClick={generate} data-testid="text-generate">
                                        {gen.busy ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />} {t('textTests.generate')}
                                    </button>
                                </div>
                                {gen.error && <div className="text-xs" style={{ color: 'var(--color-danger, #ef4444)' }}>{gen.error}</div>}
                                {form.suggestions.length > 0 && (
                                    <div className="space-y-1">
                                        <div className="text-[11px]" style={muted}>{t('textTests.pickHint')}</div>
                                        {form.suggestions.map((s, i) => (
                                            <label key={i} className="flex items-start gap-2 text-xs cursor-pointer" data-testid="text-suggestion">
                                                <input type="checkbox" className="mt-0.5" checked={s.picked}
                                                    onChange={e => setForm(f => ({ ...f, suggestions: f.suggestions.map((x, j) => (j === i ? { ...x, picked: e.target.checked } : x)) }))} />
                                                <span className="break-words">{s.text}</span>
                                            </label>
                                        ))}
                                    </div>
                                )}
                            </>
                        ) : (
                            <p className="text-xs" style={muted}>{t('textTests.aiNotConnected')}</p>
                        )}
                    </div>

                    <label className="flex flex-col gap-1 text-xs" style={muted}>
                        {t('textTests.mode')}
                        <select className="form-select text-xs" value={form.mode} onChange={e => setForm({ ...form, mode: e.target.value })}>
                            <option value="auto">{t('textTests.modeAuto')}</option>
                            <option value="equal">{t('textTests.modeEqual')}</option>
                        </select>
                    </label>
                    <div className="flex gap-2">
                        <button type="button" className="btn btn-primary text-xs" disabled={busy || !form.original_text.trim()} onClick={save} data-testid="text-test-save">
                            <Check className="w-3.5 h-3.5" /> {t('textTests.saveTest')}
                        </button>
                        <button type="button" className="btn btn-ghost text-xs" onClick={() => setForm(null)}>{t('common.cancel')}</button>
                    </div>
                </div>
            )}

            {message && <p className="text-xs" style={{ color: message.ok ? 'var(--color-success)' : 'var(--color-danger, #ef4444)' }}>{message.text}</p>}
        </div>
    );
}
